import walk as W
B=json.load(open('../bank.json',encoding='utf-8'))
Q={q['id']:q for q in B['q']}
def run(title,code,call,note=None):
    r=W.narrate(code.rstrip()+'\n'+call)
    if not r: return None
    steps=[s for s in r['steps']]
    return dict(t=title,steps=steps,out=r['out'][:200],err=r['err'],note=note)
def txt(title,lines): return dict(t=title,lines=lines)
def keycode(i): q=Q[i]; return q['options'][q['key']]
S={}
def add(i,*secs): S.setdefault(i,[]).extend(x for x in secs if x)
