# ---- độ phức tạp có code trong lựa chọn: đo ops thật
def opscount(code,n):
    ns={'n':n,'ops':0}
    try: exec(code,ns)
    except Exception: return None
    return ns['ops']
def opstable(i,title):
    q=Q[i]; ns=[8,16,32,64,128]
    hdr=['Phương án']+['n=%d'%n for n in ns]; rows=[]
    for k,o in enumerate(q['options']):
        rows.append(['ABCD'[k]+('*' if k==q['key'] else '')]+[str(opscount(o,n)) for n in ns])
    return dict(t=title,table=dict(h=hdr,r=rows))
RATIO='Nhìn cột: khi n gấp đôi, ops tăng ≈ gấp √2 lần ⇒ O(√n); +1 đơn vị ⇒ O(log n); gấp đôi ⇒ O(n); hơn gấp đôi một chút ⇒ O(n log n); gấp bốn ⇒ O(n²).'
for i,expl in [('cs11-python-do-phuc-tap-1',['Đoạn C: với mỗi i, vòng trong nhảy j += i nên chạy khoảng n/i lần ⇒ tổng n(1 + 1/2 + 1/3 + …) ≈ n ln n = O(n log n).','Đoạn B: j không bao giờ lùi nên tổng chỉ O(n). Đoạn A: chạy tới i·i ≤ n ⇒ O(√n). Đoạn D: 0 + 1 + … + (n−1) = n(n−1)/2 = O(n²).']),
 ('cs11-python-do-phuc-tap-2',['Đoạn C có while lồng for nhưng j chỉ TĂNG, không đặt lại: tổng số lần j += 1 ≤ n ⇒ tổng O(n) (kĩ thuật hai con trỏ).','Đoạn A: 0+1+…+(n−1) = O(n²). Đoạn B: vòng trong nhân đôi nên n × log n. Đoạn D: chia đôi ⇒ O(log n).']),
 ('cs11-python-do-phuc-tap-3',['Đoạn B: i //= 2 mỗi vòng nên sau ≈ log₂ n vòng i về 1 ⇒ O(log n).','A: i·i < n ⇒ O(√n). C: n/i ⇒ n log n. D: i += 1 ⇒ O(n).']),
 ('cs11-python-do-phuc-tap-4',['Đoạn C: hai vòng for đều chạy ĐỦ n lần, điều kiện if không làm giảm số lần kiểm tra ⇒ n × n = O(n²).','A: vòng trong nhân đôi ⇒ n log n. B: vòng trong chạy 3 lần ⇒ 3n. D: hai vòng tuần tự ⇒ 2n.'])]:
    add(i,opstable(i,'Đếm thật số phép ops cho từng đoạn mã'),txt('Cách đọc bảng',[RATIO]+expl))
add('cs11-python-do-phuc-tap-5',txt('Tính từng bước',['Bước 1: sắp xếp chọn so sánh (n−1) + (n−2) + … + 1 = n(n−1)/2 cặp.','Bước 2: n = 100 000 ⇒ n(n−1)/2 = 100 000 × 99 999 / 2 ≈ 5 × 10⁹ phép.','Bước 3: máy chạy 10⁸ phép/giây ⇒ thời gian = 5 × 10⁹ / 10⁸ = 50 giây.','Sai thường gặp: dùng n² = 10¹⁰ ⇒ 100 giây (gấp đôi); hoặc dùng n ⇒ 0,001 giây.']))
add('cs11-python-do-phuc-tap-6',txt('Tính từng bước',['Bước 1: n = 10⁶ ⇒ log₂ n ≈ 20 (vì 2²⁰ ≈ 10⁶).','Bước 2: số phép ≈ n log₂ n = 10⁶ × 20 = 2 × 10⁷.','Bước 3: thời gian = 2 × 10⁷ / 10⁸ = 0,2 giây (≈ 0,199).','So sánh: nếu dùng n² = 10¹² phép ⇒ 10⁴ giây ≈ 2,8 giờ — khác hẳn.']))
add('cs11-python-do-phuc-tap-7',txt('Tính từng bước',['Bước 1: n = 40 ⇒ số tập con = 2⁴⁰.','Bước 2: 2¹⁰ = 1024 ≈ 10³ ⇒ 2⁴⁰ = (2¹⁰)⁴ ≈ 10¹² (chính xác 1,1 × 10¹²).','Bước 3: máy 10⁹ phép/giây ⇒ 1,1 × 10¹² / 10⁹ ≈ 1100 giây.','Bước 4: 1100 giây / 60 ≈ 18 phút.','Nhận xét: n tăng thêm 10 thì thời gian nhân 2¹⁰ = 1024 lần ⇒ không dùng được vét cạn cho n lớn.']))
add('cs11-python-tim-kiem-8',txt('Tính từng bước',['Mỗi lần so sánh loại một nửa đoạn: n → n/2 → n/4 → … → 1.','Số lần chia đôi tối đa: ⌊log₂ n⌋ + 1.','n = 100 000: 2¹⁶ = 65 536 < 100 000 < 2¹⁷ = 131 072 ⇒ ⌊log₂ n⌋ = 16.','Số lần so sánh tối đa = 16 + 1 = 17. (Tìm tuần tự sẽ cần tới 100 000 lần.)']))
add('cs11-python-tim-kiem-tf11',txt('Đếm từng ý với a = [7, 3, 9, 3, 5, 8]',['Tìm k = 3: so sánh với a[0] = 7 (khác), a[1] = 3 (bằng) ⇒ dừng sau 2 phép. Vì hàm trả về chỉ số xuất hiện ĐẦU TIÊN nên không xét số 3 thứ hai. Ý a) đúng.','Tìm k = 4: so sánh hết 6 phần tử mà không thấy ⇒ 6 phép. Ý b) đúng.','Tìm k = 8 (phần tử cuối): phải so sánh 6 lần ⇒ xấu nhất. Ý c) đúng.','Trung bình khi k có mặt và các phần tử khác nhau: tìm vị trí 1 tốn 1 phép, vị trí 2 tốn 2, …, vị trí n tốn n ⇒ trung bình (n+1)/2 ≈ n/2, không phải n. Ý d) sai.']))
add('cs11-python-sap-xep-tf12',txt('Lần vết a = [29, 10, 14, 37, 13] từng lượt',['CHỌN, lượt 1: nhỏ nhất của cả mảng là 10 (vị trí 1) ⇒ đổi với a[0]: [10, 29, 14, 37, 13].','CHỌN, lượt 2: nhỏ nhất của a[1..] là 13 (vị trí 4) ⇒ đổi với a[1]: [10, 13, 14, 37, 29]. Ý a) đúng, ý d) sai.','CHÈN: chèn a[1] = 10 vào [29] ⇒ [10, 29, 14, 37, 13]; chèn a[2] = 14 ⇒ [10, 14, 29, 37, 13]. Ý b) đúng.','NỔI BỌT, lượt 1: so sánh cặp kề từ trái: 29>10 đổi ⇒ [10,29,14,37,13]; 29>14 đổi ⇒ [10,14,29,37,13]; 29<37 giữ; 37>13 đổi ⇒ [10,14,29,13,37]. Ý c) đúng.']))
q=Q['cs11-python-sap-xep-13']
SEL="def chon(a):\n    a=list(a)\n    for i in range(len(a)-1):\n        m=i\n        for j in range(i+1,len(a)):\n            if a[j][0]<a[m][0]: m=j\n        a[i],a[m]=a[m],a[i]\n    return a\n"
INS="def chen(a):\n    a=list(a)\n    for i in range(1,len(a)):\n        x=a[i];j=i-1\n        while j>=0 and a[j][0]>x[0]:\n            a[j+1]=a[j];j-=1\n        a[j+1]=x\n    return a\n"
add('cs11-python-sap-xep-13',run('Sắp xếp CHỌN trên [(2,a), (2,b), (1,c)]',SEL,"print(chon([(2,'a'),(2,'b'),(1,'c')]))"),run('Sắp xếp CHÈN trên cùng dữ liệu',INS,"print(chen([(2,'a'),(2,'b'),(1,'c')]))"),txt('Kết luận',['Chọn: khoá nhỏ nhất (1,c) được đổi chỗ XA với (2,a) ⇒ (2,a) nhảy ra sau (2,b): thứ tự a, b bị đảo ⇒ KHÔNG ổn định ⇒ c, b, a.','Chèn: chỉ dịch các phần tử LỚN HƠN hẳn (a[j] > x), không bao giờ vượt qua phần tử bằng ⇒ giữ nguyên a, b ⇒ ổn định ⇒ c, a, b.']))
add('cs11-python-sap-xep-tf15',txt('Giải từng ý với n = 8',['Số phép so sánh luôn là (n−1) + (n−2) + … + 1 = 7 + 6 + … + 1 = 28, với mọi dữ liệu vì vòng trong luôn quét hết đoạn còn lại. Ý a) đúng.','Mỗi lượt đổi chỗ tối đa một lần, có n−1 = 7 lượt ⇒ không quá 7 lần. Ý b) đúng.','Mảng đã sắp xếp vẫn phải quét để tìm nhỏ nhất ⇒ vẫn 28 phép so sánh ⇒ độ phức tạp vẫn O(n²) (không xuống O(n)). Ý c) sai.','Mảng đã sắp xếp: phần tử nhỏ nhất của a[i..] luôn là a[i] ⇒ "đổi chỗ nếu cần" không xảy ra ⇒ 0 lần đổi. Ý d) đúng.']))
FQ="def f(n):\n    ops_calls[0]+=1\n    if n<=1: return 1\n    return n+0*f(n-1)\n"
add('cs11-python-de-quy-18',txt('Lập hệ thức T(n) cho từng hàm',['A: mỗi lần gọi tốn 1 phép và gọi MỘT bài con n/2: T(n) = T(n/2) + 1 ⇒ O(log n).','B: gọi HAI bài con n−1: T(n) = 2T(n−1) + 1 ⇒ O(2ⁿ).','C: mỗi lần tốn n phép, một bài con n−1: T(n) = T(n−1) + n = n + (n−1) + … + 1 ⇒ O(n²).','D: tốn n phép ghép và gọi HAI bài con cỡ n/2: T(n) = 2T(n/2) + n. Mỗi tầng của cây đệ quy tốn tổng n phép, có log₂ n tầng ⇒ O(n log n) (giống sắp xếp trộn).']))
add('cs11-python-de-quy-tf19',run('Ý a) tong(5) minh hoạ cách đệ quy chạy (tong(100) tương tự = 5050)',"def tong(n):\n    if n == 0:\n        return 0\n    return n + tong(n - 1)\n",'print(tong(5))'),txt('Giải từng ý',['Ý a) tong(n) = n + (n−1) + … + 1 = n(n+1)/2: n = 100 ⇒ 5050. Đúng.','Ý b) mỗi lời gọi đệ quy chiếm một khung trong ngăn xếp; Python mặc định giới hạn 1000 khung. tong(5000) cần 5001 khung ⇒ RecursionError. Đúng.','Ý c) bộ nhớ ngăn xếp tăng theo n (n khung) ⇒ O(n), không phải O(1). Sai.','Ý d) công thức n(n+1)/2 tính trực tiếp, không vòng lặp ⇒ O(1). Đúng.']))
add('cs11-python-thuat-toan-nc-tf23',txt('Giải từng ý',['Tham lam {1, 3, 4}, m = 6: lấy 4 (còn 2) → không lấy được 3 → lấy 1 (còn 1) → lấy 1 (còn 0): 3 tờ (4 + 1 + 1). Ý a) đúng.','Tối ưu: 3 + 3 = 6 chỉ 2 tờ ⇒ tham lam KHÔNG tối ưu với hệ này. Ý b) đúng.','{1, 5, 10, 25}, m = 41: 25 → 16; 10 → 6; 5 → 1; 1 → 0: 4 tờ (25 + 10 + 5 + 1). Với hệ chuẩn như thế này tham lam tối ưu. Ý c) đúng.','Ý d) sai: nhanh hơn không có nghĩa luôn đúng; ví dụ {1,3,4} đã là phản ví dụ. Muốn đúng với mọi hệ cần quy hoạch động.']))
add('cs11-python-do-phuc-tap-tf29',txt('Giải từng ý',['Ý a) Giữ số hạng bậc cao nhất và bỏ hệ số: 3n² + 5n log n + 100 = O(n²). Đúng.','Ý b) Vòng trong chỉ chạy 3 lần (hằng số) ⇒ 3n phép ⇒ O(n). Có hai vòng lồng nhau KHÔNG có nghĩa luôn là O(n²). Sai.','Ý c) Quy tắc cộng: hai đoạn nối tiếp O(n²) và O(n log n) ⇒ lấy số hạng lớn hơn: O(n²). Đúng.','Ý d) O(n log n) chỉ nhanh hơn O(n²) khi n đủ lớn; với n nhỏ hệ số hằng có thể làm ngược lại. Sai.']))
add('cs11-python-do-phuc-tap-30',txt('Cách đánh giá',['Ba trường hợp: tốt nhất 1 (tìm thấy ngay), trung bình n/2, xấu nhất n.','Khi so sánh thuật toán người ta thường dùng TRƯỜNG HỢP XẤU NHẤT làm cận trên vì nó bảo đảm thời gian không vượt quá mức đó với mọi dữ liệu ⇒ O(n).','n/2 và n cùng bậc O(n) vì bỏ hệ số hằng. Không lấy trung bình cộng ba trường hợp (sẽ ≈ n/2 chứ không phải O(1)).']))
add('cs11-python-do-phuc-tap-32',txt('Phân tích từng cách',['Đổi chỗ tại chỗ: chỉ cần vài biến i, j (và biến tạm) ⇒ bộ nhớ phụ O(1).','Tạo danh sách mới b: thêm n phần tử ⇒ O(n).','Đệ quy với đảo(a[1:]): mỗi lần cắt lát tạo bản sao + n lời gọi lồng nhau ⇒ O(n) khung ngăn xếp và O(n²) tổng bộ nhớ tạm.','Dùng ngăn xếp: lưu n phần tử ⇒ O(n).']))
