add('bn_b-python-thuat-toan-nc-15',txt('Giải từng bước',['Một số là số chính phương ⇔ trong phân tích ra thừa số nguyên tố, MỌI số mũ đều chẵn (ví dụ 36 = 2²·3²).','Tích a[L]·…·a[R]: số mũ của mỗi nguyên tố p trong tích = tổng số mũ của p ở các phần tử. Tích là chính phương ⇔ tổng đó chẵn với MỌI p, tức mỗi nguyên tố xuất hiện một số chẵn lần trong phân tích của tích.','Phản ví dụ cho các phương án khác: [15, 15, 4] có tích 900 = 30² là chính phương nhưng không phần tử nào (15, 15) là chính phương riêng; tổng 15 + 15 + 4 = 34 không phải chính phương.']))
add('bn_b-python-thuat-toan-nc-16',txt('Giải từng bước',['Ý tưởng: dùng "tích tiền tố". Gọi P[i] = a[1]·…·a[i]. Khi đó tích đoạn a[L..R] = P[R] / P[L−1].','Mask[i] ghi lại các nguyên tố có số mũ LẺ trong P[i]. Số mũ trong đoạn = số mũ ở P[R] − số mũ ở P[L−1]; một số mũ là chẵn ⇔ hai số mũ cùng tính chẵn/lẻ.','Vậy đoạn có tích chính phương ⇔ mọi nguyên tố có cùng tính chẵn/lẻ ở hai tiền tố ⇔ mask[R] = mask[L−1] (XOR của hai mask rỗng).','Mỗi truy vấn chỉ so sánh hai mask: nếu lưu mask bằng bảng băm thì O(1) trung bình.']))
add('bn_b-python-thuat-toan-nc-18',txt('So sánh các thuật toán',['Bài toán: tìm các đỉnh (con bò) không liên thông với bò 1 trong đồ thị n đỉnh, m cạnh (dây thừng).','BFS/DFS từ bò 1 với danh sách kề: mỗi đỉnh và mỗi cạnh được xét đúng một lần ⇒ O(n + m). Đỉnh nào không được thăm là đáp án.','Sắp xếp cạnh rồi tìm nhị phân: không cho biết tính liên thông.','Thử mọi đường đi (O(2ⁿ)) hay mọi hoán vị (O(n!)): quá chậm, n tới 250.']))
add('bn_b-python-thuat-toan-nc-19',txt('Tìm số phép biến đổi ít nhất cho a = [2, 6, 4, 3, 2]',['Cần dãy đích b KHÔNG GIẢM sao cho tổng |a_i − b_i| nhỏ nhất.','Thử dãy đích b = [2, 4, 4, 4, 4]: |2−2| + |6−4| + |4−4| + |3−4| + |2−4| = 0 + 2 + 0 + 1 + 2 = 5.','Các cách làm tham lam sai cho số khác: chỉ tăng các phần tử thấp lên bằng max hiện tại cho tổng lớn hơn (ví dụ 9); chỉ giảm các phần tử cao xuống cũng không tối ưu.','Kiểm tra bằng vét cạn mọi dãy đích không giảm giá trị 1..10: nhỏ nhất là 5 ⇒ đáp án B.']))
add('bn_b-python-thuat-toan-nc-20',txt('Vì sao chỉ cần thử các giá trị của chính dãy',['Hàm chi phí theo giá trị đích v của một phần tử là tổng các |a_i − v|: tuyến tính từng đoạn, "gãy" tại các giá trị a_i.','Cực tiểu của hàm tuyến tính từng đoạn luôn nằm tại một điểm gãy ⇒ tồn tại phương án tối ưu mà mọi giá trị đích đều bằng một phần tử nào đó của dãy.','Nhờ vậy quy hoạch động chỉ cần xét n giá trị v thay vì cả miền giá trị lớn.']))
add('bn_b-python-do-phuc-tap-22',txt('Ước lượng số thao tác',['Số trạng thái f[i][v]: n × V = 100 000 × 10 000 = 10⁹.','Mỗi trạng thái ít nhất một phép tính ⇒ ≈ 10⁹ thao tác.','Máy chấm thường chạy ≈ 10⁸ phép đơn giản mỗi giây ⇒ 10⁹ cần khoảng 10 giây, vượt giới hạn 1–2 giây ⇒ KHÔNG kịp, cần cải tiến thuật toán.']))
add('bn_b-python-do-phuc-tap-24',txt('Phân tích',['Hai vòng lặp lồng nhau trên N = 10⁵ phần tử: trường hợp xấu nhất vòng trong chạy tới N lần ⇒ ≈ N²/2 ~ 10¹⁰ phép — quá lớn.','Vòng trong chỉ cần xét các vị trí j trong "cửa sổ" mà chênh lệch không vượt V ⇒ dùng CỬA SỔ TRƯỢT với HÀNG ĐỢI ĐƠN ĐIỆU để lấy min/max trong cửa sổ ở O(1) mỗi bước ⇒ tổng O(N).']))
